import sys; sys.path.insert(0,"/workspace/social/posts"); from build10 import build
B=r'''<style>.box p,.box li{font-size:19.5px;line-height:1.28}.box h2{font-size:25px;margin-bottom:5px}.tbl{font-size:17.5px}.tbl th,.tbl td{padding:3px 6px}.iq ol{font-size:18.5px;line-height:1.28}.pill{font-size:15px}.grid{gap:10px}.handle{bottom:-12px}.box{padding:9px 12px}.tagline{font-size:19px;margin-bottom:6px}</style>
<div class="title">📦 HxGN EAM Held Items <span class="badge">CHEAT SHEET</span></div>
<div class="tagline">Receive parts for a specific work order straight to the WO or to a held-item bin, issue them as packages, and move them between held and stock bins. (Infor EAM Held Items brief, 11.6.1)</div>
<div class="grid">
<div class="box c1"><h2>1. What is a held item?</h2><ul><li>A part received for a <b>work order</b> instead of into a normal stock bin</li><li>Skips middle receiving steps = better productivity</li><li>Received <b>direct to WO</b> or to a <b>held-item bin</b></li><li>Issued / returned as a <b>package</b></li></ul></div>
<div class="box c2"><h2>2. Organization Options</h2><table class="tbl"><tr><th>Option</th><th>Values (default)</th></tr><tr><td><b>PDRCPTTO</b></td><td>WO / HELD (WO): Direct to WO ticked or not by default</td></tr><tr><td><b>HELDBINS</b></td><td>OPTIONAL / PROTECTED / REQUIRED (PROTECTED): Bin field on direct-purchase receipt</td></tr></table></div>
<div class="box c3"><h2>3. Stores › Bins tab</h2><ul><li>Each bin: <b>For Stock</b> ✔ and/or <b>For Held Items</b> ✔</li><li>For Stock is ticked by default</li><li>Any combination is allowed</li></ul></div>
<div class="box c4"><h2>4. PO Receipts › Active Lines</h2><ul><li>Direct Materials line → <b>Direct to WO</b> ✔ + WO–Activity filled</li><li>Direct to WO ✔ = received to the WO</li><li>Direct to WO ✘ = received to the store as a <b>Held Item</b></li><li>Bin field follows HELDBINS</li></ul></div>
<div class="box c5"><h2>5. Non-PO Receipts › Parts</h2><ul><li>Fill <b>Hold for Work Order–Activity</b> = held item</li><li>Bin field then follows HELDBINS</li><li>Clear it and Bin goes back to <b>Required</b></li></ul></div>
<div class="box c6"><h2>6. Packages</h2><ul><li>Status: Unfinished → <b>Approved</b> (or Canceled)</li><li>Issue/Return Parts on Approved = <b>Issue Mode</b>, status becomes <b>Issued</b></li><li>On Issued = <b>Return Mode</b> (Fill / Clear Return Qty.)</li><li>Issued To (employee) required; Parts + Transactions tabs</li></ul></div>
<div class="box c7"><h2>7. Three transfer screens</h2><table class="tbl"><tr><th>Screen</th><th>Moves</th></tr><tr><td>Held Items Transfer</td><td>held bin → held bin (same or other store)</td></tr><tr><td>Held Items to Stock Transfer</td><td>held bin → stock bin</td></tr><tr><td>Stock to Held Items Transfer</td><td>stock bin → held bin (WO–Activity required)</td></tr></table></div>
<div class="box c8"><h2>8. Labels &amp; transfer rules</h2><ul><li>Label Templates for each held-item transaction on <b>Stores</b> and <b>Parts › Stores tab</b></li><li>Parts › Stores tab is checked first, then the Store</li><li>Header: Description, From/To Store, Default To Bin</li><li>Track by Asset part → Transfer Qty. fixed at <b>1</b></li></ul></div>
<div class="bottom">
<div class="box" style="border-color:#1a5f7a"><h2 style="color:#1a5f7a">9a. Held item flow</h2><div class="flow" style="flex-wrap:wrap;row-gap:4px"><span class="pill">PO / Non-PO receipt</span><span class="arr">→</span><span class="pill">Held bin (for WO)</span><span class="arr">→</span><span class="pill">Package Approved</span><span class="arr">→</span><span class="pill">Issued</span><span class="arr">→</span><span class="pill">Return / to stock</span></div></div>
<div class="box iq"><h2>9b. Consultant tips</h2><ol><li>Decide PDRCPTTO with stores team before go-live</li><li>Create dedicated held-item bins</li><li>Set held-item label templates per store</li><li>Move leftovers back with Held Items to Stock</li></ol></div>
<div class="box" style="border-color:#2d8a5a"><h2 style="color:#2d8a5a">9c. Key points</h2><ul><li>Direct to WO ✘ = held</li><li>HELDBINS drives Bin</li><li>Approved → Issued</li></ul></div>
</div></div>'''
build("/workspace/social/posts/2026-10-21-linkedin-eam-held-items",B,1350,"Rahul Kumar")
